def correct_bracketing(brackets: str) -> bool:
    # Validate the input string to ensure it only contains '<' and '>' characters
    if any(char not in ['<', '>'] for char in brackets):
        return False

    # Count the number of opening and closing brackets in the input string
    opening_count = brackets.count('<')
    closing_count = brackets.count('>')

    # Ensure that each opening bracket has a corresponding closing bracket
    if opening_count != closing_count:
        return False

    # Iterate through the input string to check for correct bracketing
    stack = []
    for char in brackets:
        if char == '<':
            stack.append(char)
        elif char == '>':
            if not stack:
                return False
            stack.pop()

    # Return True if all conditions are met, otherwise return False
    return len(stack) == 0

